<!-- ─── HERO ────────────────────────────────────────────── -->
<section class="hero" aria-label="Hero">
  <!-- Mosaic poster backdrop -->
  <div class="hero-mosaic" aria-hidden="true">
    <div class="pm pm-1"></div><div class="pm pm-2"></div><div class="pm pm-3"></div><div class="pm pm-4"></div>
    <div class="pm pm-5"></div><div class="pm pm-6"></div><div class="pm pm-7"></div><div class="pm pm-8"></div>
    <div class="pm pm-9"></div><div class="pm pm-10"></div><div class="pm pm-11"></div><div class="pm pm-12"></div>
    <div class="pm pm-13"></div><div class="pm pm-14"></div><div class="pm pm-15"></div><div class="pm pm-16"></div>
    <div class="pm pm-1"></div><div class="pm pm-3"></div><div class="pm pm-5"></div><div class="pm pm-7"></div>
    <div class="pm pm-9"></div><div class="pm pm-11"></div><div class="pm pm-2"></div><div class="pm pm-4"></div>
    <div class="pm pm-6"></div><div class="pm pm-8"></div><div class="pm pm-10"></div><div class="pm pm-12"></div>
    <div class="pm pm-14"></div><div class="pm pm-16"></div><div class="pm pm-1"></div><div class="pm pm-5"></div>
    <div class="pm pm-3"></div><div class="pm pm-7"></div><div class="pm pm-9"></div><div class="pm pm-11"></div>
    <div class="pm pm-2"></div><div class="pm pm-4"></div><div class="pm pm-6"></div><div class="pm pm-8"></div>
    <div class="pm pm-10"></div><div class="pm pm-12"></div><div class="pm pm-14"></div><div class="pm pm-16"></div>
    <div class="pm pm-1"></div><div class="pm pm-3"></div><div class="pm pm-5"></div><div class="pm pm-7"></div>
    <div class="pm pm-9"></div><div class="pm pm-11"></div><div class="pm pm-13"></div><div class="pm pm-15"></div>
    <div class="pm pm-2"></div><div class="pm pm-4"></div><div class="pm pm-6"></div><div class="pm pm-8"></div>
    <div class="pm pm-10"></div><div class="pm pm-12"></div><div class="pm pm-14"></div><div class="pm pm-16"></div>
    <div class="pm pm-1"></div><div class="pm pm-5"></div><div class="pm pm-9"></div><div class="pm pm-13"></div>
  </div>
  <div class="hero-overlay" aria-hidden="true"></div>

  <div class="hero-content">
    <h1 class="hero-title">Unlimited films,<br>series and more</h1>
    <p class="hero-subtitle">Starts at $15.98. Cancel at any time.</p>
    <p class="hero-prompt">Ready to watch? Enter your email to create or restart your membership.</p>
    <form class="email-form" id="hero-form" novalidate>
      <label for="hero-email" class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)">Email address</label>
