<!-- ─── TRENDING ─────────────────────────────────────────── -->
<section class="trending-section" aria-label="Trending Now">
  <h2 class="section-title">Trending Now</h2>
  <div class="carousel-outer" id="carousel-outer">
    <div class="carousel-viewport">
      <div class="carousel-track" id="carousel-track" role="list">

        <div class="poster-card" role="listitem">
          <div class="pc-bg pc-1"></div>
          <div class="poster-rank" aria-hidden="true">1</div>
