          <div class="pc-title-overlay">BEEF</div>
        </div>

        <div class="poster-card" role="listitem">
          <div class="pc-bg pc-3"></div>
          <div class="poster-rank" aria-hidden="true">3</div>
          <div class="pc-title-overlay">XO, Kitty</div>
        </div>

        <div class="poster-card" role="listitem">
          <div class="pc-bg pc-4"></div>
          <div class="poster-rank" aria-hidden="true">4</div>
