<script>
  // Password show/hide toggle
  const passInput = document.getElementById('login-password');
  const passToggle = document.getElementById('password-toggle');

  passToggle.addEventListener('click', () => {
    const isPassword = passInput.type === 'password';
    passInput.type = isPassword ? 'text' : 'password';
    passToggle.textContent = isPassword ? 'HIDE' : 'SHOW';
    passToggle.setAttribute('aria-pressed', isPassword ? 'true' : 'false');
    passToggle.setAttribute('aria-label', isPassword ? 'Hide password' : 'Show password');
  });

  // Get Help toggle
  const helpToggle = document.getElementById('help-toggle');
  const helpPanel = document.getElementById('help-panel');

  helpToggle.addEventListener('click', () => {
    const isOpen = helpPanel.classList.contains('open');
    helpPanel.classList.toggle('open', !isOpen);
    helpToggle.classList.toggle('open', !isOpen);
    helpToggle.setAttribute('aria-expanded', !isOpen ? 'true' : 'false');
    helpPanel.setAttribute('aria-hidden', isOpen ? 'true' : 'false');
  });

  // Login form validation
  const form = document.getElementById('login-form');
  const emailInput = document.getElementById('login-email');
  const fieldEmail = document.getElementById('field-email');
  const fieldPassword = document.getElementById('field-password');

  function clearErrors() {
    fieldEmail.classList.remove('has-error');
    fieldPassword.classList.remove('has-error');
    emailInput.classList.remove('error');
    passInput.classList.remove('error');
  }

  emailInput.addEventListener('input', clearErrors);
  passInput.addEventListener('input', clearErrors);

  form.addEventListener('submit', e => {
    e.preventDefault();
    clearErrors();

    let valid = true;
    const emailVal = emailInput.value.trim();
    const passVal = passInput.value;

    if (!emailVal) {
      fieldEmail.classList.add('has-error');
      emailInput.classList.add('error');
      valid = false;
    }

    if (passVal.length < 4) {
      fieldPassword.classList.add('has-error');
      passInput.classList.add('error');
      valid = false;
    }

    if (!valid) return;

    // Simulate submit — in production this would POST to an endpoint
    const btn = document.getElementById('submit-btn');
    btn.textContent = 'Signing in…';
    btn.disabled = true;
    // Reset after demo delay
    setTimeout(() => {
      btn.textContent = 'Continue';
      btn.disabled = false;
    }, 1800);
  });
</script>

